ALTER TABLE rate_plans ADD COLUMN base_price INTEGER;
CREATE TABLE IF NOT EXISTS pending_events (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  type TEXT,
  hotel_id TEXT,
  target_date TEXT,
  payload_json TEXT,
  armed_at TEXT,
  armed_day INTEGER,
  consumed_at TEXT
);
